import { and, eq, isNull, sql } from 'drizzle-orm'
import { db } from '../db/client.js'
import { notes } from '../db/schema.js'
import { embedder } from './embeddings.js'
import { recomputeSemanticEdges } from './semantic-edges.js'

// ponytail: in-process serial queue; move to a job table if multi-process
const queue: string[] = []
let running: Promise<void> | null = null

/** Enqueue a note for (re-)embedding. Never blocks the caller (perf rule 2). */
export function scheduleEmbedding(noteId: string): void {
  queue.push(noteId)
  running ??= drain().finally(() => {
    running = null
  })
}

/** Awaits until the queue is empty — tests and batch jobs only. */
export async function flushEmbeddings(): Promise<void> {
  while (running) await running
}

/** Boot catch-up: enqueue live notes that never got an embedding. */
export async function scheduleMissingEmbeddings(): Promise<number> {
  const missing = await db
    .select({ id: notes.id })
    .from(notes)
    .where(and(isNull(notes.deletedAt), sql`${notes.embedding} is null`))
  for (const row of missing) scheduleEmbedding(row.id)
  return missing.length
}

async function drain(): Promise<void> {
  while (queue.length > 0) {
    const noteId = queue.shift()!
    try {
      await processNote(noteId)
    } catch (err) {
      console.error(`embedding failed for note ${noteId}:`, err)
    }
  }
}

async function processNote(noteId: string): Promise<void> {
  const row = (await db.select().from(notes).where(eq(notes.id, noteId)))[0]
  if (!row || row.deletedAt) return
  const text = `${row.path}\n${JSON.stringify(row.frontmatter)}\n${row.body}`
  const [embedding] = await embedder.embed([text])
  await db.update(notes).set({ embedding }).where(eq(notes.id, noteId))
  await recomputeSemanticEdges('note', noteId, embedding!)
}

import { sql, type SQL } from 'drizzle-orm'
import { db } from '../db/client.js'
import { embedder } from './embeddings.js'

function uuidArray(ids: string[]): SQL {
  return sql`ARRAY[${sql.join(
    ids.map((id) => sql`${id}::uuid`),
    sql`, `,
  )}]`
}

export type ResourceType = 'note' | 'code'

export interface SearchResourceSet {
  vaultIds: string[]
  repositoryIds: string[]
}

export interface SearchResult {
  resourceType: ResourceType
  id: string // noteId or repositoryFileId
  containerId: string // vaultId or repositoryId
  path: string
  frontmatter?: unknown // notes only
  language?: string | null // code only
  snippet: string
  score: number
}

const CANDIDATES = 30
const RRF_K = 60

interface Row {
  id: string
  container_id: string
  path: string
  frontmatter?: unknown
  language?: string | null
  snippet: string
}

async function noteRows(vaultIds: string[], query: string, mode: 'keyword' | 'semantic', vec?: string): Promise<Row[]> {
  if (vaultIds.length === 0) return []
  const rows =
    mode === 'keyword'
      ? await db.execute(sql`
          SELECT id, vault_id AS container_id, path, frontmatter,
                 ts_headline('english', body, websearch_to_tsquery('english', ${query}),
                             'MaxWords=30, MinWords=10') AS snippet
          FROM notes
          WHERE vault_id = ANY(${uuidArray(vaultIds)})
            AND deleted_at IS NULL
            AND fts @@ websearch_to_tsquery('english', ${query})
          ORDER BY ts_rank(fts, websearch_to_tsquery('english', ${query})) DESC
          LIMIT ${CANDIDATES}
        `)
      : await db.execute(sql`
          SELECT id, vault_id AS container_id, path, frontmatter, left(body, 200) AS snippet
          FROM notes
          WHERE vault_id = ANY(${uuidArray(vaultIds)})
            AND deleted_at IS NULL
            AND embedding IS NOT NULL
          ORDER BY embedding <=> ${vec}::vector
          LIMIT ${CANDIDATES}
        `)
  return rows as unknown as Row[]
}

async function codeRows(repositoryIds: string[], query: string, mode: 'keyword' | 'semantic', vec?: string): Promise<Row[]> {
  if (repositoryIds.length === 0) return []
  const rows =
    mode === 'keyword'
      ? await db.execute(sql`
          SELECT id, repository_id AS container_id, path, language,
                 ts_headline('english', content, websearch_to_tsquery('english', ${query}),
                             'MaxWords=30, MinWords=10') AS snippet
          FROM repository_files
          WHERE repository_id = ANY(${uuidArray(repositoryIds)})
            AND fts @@ websearch_to_tsquery('english', ${query})
          ORDER BY ts_rank(fts, websearch_to_tsquery('english', ${query})) DESC
          LIMIT ${CANDIDATES}
        `)
      : await db.execute(sql`
          SELECT id, repository_id AS container_id, path, language, left(content, 200) AS snippet
          FROM repository_files
          WHERE repository_id = ANY(${uuidArray(repositoryIds)})
            AND embedding IS NOT NULL
          ORDER BY embedding <=> ${vec}::vector
          LIMIT ${CANDIDATES}
        `)
  return rows as unknown as Row[]
}

/**
 * The one search function every caller uses (spec 4/9: human UI and MCP
 * share one path across both notes and code — results never diverge).
 * Hybrid retrieval: Postgres FTS + embedding KNN, merged by Reciprocal
 * Rank Fusion. The permission boundary is `resources` — resolved live by
 * the caller; the SQL never touches anything outside it, so absence of
 * access is absence from the result set (no counts, no hints).
 */
export async function searchNotes(
  resources: SearchResourceSet,
  query: string,
  limit = 20,
): Promise<SearchResult[]> {
  const { vaultIds, repositoryIds } = resources
  if ((vaultIds.length === 0 && repositoryIds.length === 0) || query.trim() === '') return []

  const [queryVec] = await embedder.embed([query])
  const vec = JSON.stringify(queryVec)

  const [noteKeyword, noteSemantic, codeKeyword, codeSemantic] = await Promise.all([
    noteRows(vaultIds, query, 'keyword'),
    noteRows(vaultIds, query, 'semantic', vec),
    codeRows(repositoryIds, query, 'keyword'),
    codeRows(repositoryIds, query, 'semantic', vec),
  ])

  // Reciprocal Rank Fusion — rank-based, no score normalization to tune.
  const merged = new Map<string, SearchResult>()
  const contribute = (resourceType: ResourceType, rows: Row[], preferSnippet: boolean): void => {
    rows.forEach((row, rank) => {
      const key = `${resourceType}:${row.id}`
      const contribution = 1 / (RRF_K + rank + 1)
      const existing = merged.get(key)
      if (existing) {
        existing.score += contribution
        if (preferSnippet) existing.snippet = row.snippet
      } else {
        merged.set(key, {
          resourceType,
          id: row.id,
          containerId: row.container_id,
          path: row.path,
          frontmatter: resourceType === 'note' ? row.frontmatter : undefined,
          language: resourceType === 'code' ? row.language : undefined,
          snippet: row.snippet,
          score: contribution,
        })
      }
    })
  }
  contribute('note', noteSemantic, false)
  contribute('code', codeSemantic, false)
  contribute('note', noteKeyword, true) // keyword snippets (highlighted) win
  contribute('code', codeKeyword, true)

  return [...merged.values()].sort((a, b) => b.score - a.score).slice(0, limit)
}

import { and, eq, isNull, ne, or, sql } from 'drizzle-orm'
import { db } from '../db/client.js'
import { notes, repositoryFiles, semanticEdges } from '../db/schema.js'
import { config } from '../config.js'

export type SemanticNodeType = 'note' | 'code'

interface Neighbor {
  type: SemanticNodeType
  id: string
  similarity: number
}

async function knn(
  vec: string,
  excludeType: SemanticNodeType,
  excludeId: string,
): Promise<Neighbor[]> {
  const noteRows = await db
    .select({ id: notes.id, similarity: sql<number>`1 - (${notes.embedding} <=> ${vec}::vector)` })
    .from(notes)
    .where(
      and(
        isNull(notes.deletedAt),
        sql`${notes.embedding} is not null`,
        excludeType === 'note' ? ne(notes.id, excludeId) : sql`true`,
      ),
    )
    .orderBy(sql`${notes.embedding} <=> ${vec}::vector`)
    .limit(config.semanticK)

  const codeRows = await db
    .select({
      id: repositoryFiles.id,
      similarity: sql<number>`1 - (${repositoryFiles.embedding} <=> ${vec}::vector)`,
    })
    .from(repositoryFiles)
    .where(
      and(
        sql`${repositoryFiles.embedding} is not null`,
        excludeType === 'code' ? ne(repositoryFiles.id, excludeId) : sql`true`,
      ),
    )
    .orderBy(sql`${repositoryFiles.embedding} <=> ${vec}::vector`)
    .limit(config.semanticK)

  return [
    ...noteRows.map((r) => ({ type: 'note' as const, id: r.id, similarity: r.similarity })),
    ...codeRows.map((r) => ({ type: 'code' as const, id: r.id, similarity: r.similarity })),
  ]
    .sort((a, b) => b.similarity - a.similarity)
    .slice(0, config.semanticK)
}

/**
 * Recomputes one node's semantic neighbors across both notes and code
 * (spec 9: one shared embedding space, semantic edges span both content
 * types) and stores the strong ones. Called by both the note embedding
 * queue and the repository file extraction queue.
 */
export async function recomputeSemanticEdges(
  nodeType: SemanticNodeType,
  nodeId: string,
  embedding: number[],
): Promise<void> {
  await db
    .delete(semanticEdges)
    .where(
      or(
        and(eq(semanticEdges.nodeAType, nodeType), eq(semanticEdges.nodeAId, nodeId)),
        and(eq(semanticEdges.nodeBType, nodeType), eq(semanticEdges.nodeBId, nodeId)),
      ),
    )

  const vec = JSON.stringify(embedding)
  const neighbors = (await knn(vec, nodeType, nodeId)).filter(
    (n) => n.similarity >= config.semanticThreshold,
  )
  if (neighbors.length === 0) return

  const self = { type: nodeType, id: nodeId }
  const rows = neighbors.map((n) => {
    const [a, b] = `${self.type}:${self.id}` < `${n.type}:${n.id}` ? [self, n] : [n, self]
    return {
      nodeAType: a.type,
      nodeAId: a.id,
      nodeBType: b.type,
      nodeBId: b.id,
      similarity: n.similarity,
    }
  })
  await db
    .insert(semanticEdges)
    .values(rows)
    .onConflictDoUpdate({
      target: [semanticEdges.nodeAType, semanticEdges.nodeAId, semanticEdges.nodeBType, semanticEdges.nodeBId],
      set: { similarity: sql`excluded.similarity` },
    })
}

import type { FastifyInstance } from 'fastify'
import { atLeast, listAccessibleVaults, resolveAccess } from '../vaults/permissions.js'
import { listAccessibleRepositories } from '../repositories/permissions.js'
import { searchNotes } from './search.js'

const searchQuerySchema = {
  type: 'object',
  required: ['q'],
  properties: {
    q: { type: 'string', minLength: 1, maxLength: 500 },
    limit: { type: 'integer', minimum: 1, maximum: 100, default: 20 },
  },
} as const

export function searchRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  app.get<{ Params: { id: string }; Querystring: { q: string; limit?: number } }>(
    '/vaults/:id/search',
    { schema: { querystring: searchQuerySchema } },
    async (req, reply) => {
      const access = await resolveAccess(req.user!.id, req.params.id)
      if (!atLeast(access, 'read')) return reply.code(404).send({ error: 'not found' })
      return searchNotes({ vaultIds: [req.params.id], repositoryIds: [] }, req.query.q, req.query.limit)
    },
  )

  /**
   * "Search everywhere": every vault and repository the caller can
   * currently reach — not gated by mergeable/graph-preference, a
   * deliberately different (broader) scope than the merged graph view.
   */
  app.get<{ Querystring: { q: string; limit?: number } }>(
    '/search',
    { schema: { querystring: searchQuerySchema } },
    async (req) => {
      const [accessibleVaults, accessibleRepos] = await Promise.all([
        listAccessibleVaults(req.user!.id),
        listAccessibleRepositories(req.user!.id),
      ])
      return searchNotes(
        {
          vaultIds: accessibleVaults.map((v) => v.id),
          repositoryIds: accessibleRepos.map((r) => r.id),
        },
        req.query.q,
        req.query.limit,
      )
    },
  )
}

import { Server, type Hocuspocus } from '@hocuspocus/server'
import type * as Y from 'yjs'
import { getSessionUser } from '../auth/sessions.js'
import { atLeast, resolveAccess } from '../vaults/permissions.js'
import { readNote, updateNote, splitPath } from '../notes/store.js'
import { logSecurityEvent } from '../auth/security-events.js'
import { affects, onPermissionChange } from './permission-events.js'
import { publishNoteState } from './viewers.js'

const DEBOUNCE_MS = Number(process.env.COLLAB_DEBOUNCE_MS ?? 2000)

function parseDocName(name: string): { vaultId: string; path: string } {
  const slash = name.indexOf('/')
  if (slash === -1) throw new Error(`invalid document name: ${name}`)
  const vaultId = name.slice(0, slash)
  const path = name.slice(slash + 1)
  splitPath(path) // validates type/name slugs
  return { vaultId, path }
}

interface ConnectionContext {
  userId: string
}

function docState(document: Y.Doc): { frontmatter: Record<string, unknown>; body: string } {
  return {
    frontmatter: document.getMap('frontmatter').toJSON(),
    body: document.getText('body').toString(),
  }
}

/**
 * The sync relay (spec 5 + audit hardening), running as Hocuspocus's own
 * Server on a dedicated port in the same process. Editors only —
 * read-only live viewers are served via the SSE hub and never join here.
 * MCP writes (sub-project 6) use openDirectConnection on this instance,
 * so every AI edit is a visible participant in the same engine.
 */
let currentInstance: Hocuspocus | null = null

/** The running relay instance, if any — MCP writes route through it. */
export function getCollab(): Hocuspocus | null {
  return currentInstance
}

export async function startCollabServer(port: number): Promise<Server> {
  const server = new Server({
    port,
    debounce: DEBOUNCE_MS,
    maxDebounce: DEBOUNCE_MS * 5,
    quiet: true,

    async onAuthenticate({ token, documentName }) {
      const user = token ? await getSessionUser(token) : null
      if (!user) throw new Error('authentication required')
      const { vaultId } = parseDocName(documentName)
      const access = await resolveAccess(user.id, vaultId)
      if (!atLeast(access, 'edit')) {
        await logSecurityEvent({
          type: 'permission_denied',
          actorUserId: user.id,
          detail: { surface: 'collab', documentName },
        })
        throw new Error('edit access required')
      }
      return { userId: user.id } satisfies ConnectionContext
    },

    async onLoadDocument({ documentName, document }) {
      const { vaultId, path } = parseDocName(documentName)
      const note = await readNote(vaultId, path)
      if (!note) throw new Error(`note does not exist: ${documentName}`)
      const body = document.getText('body')
      if (body.length === 0) body.insert(0, note.body)
      const fm = document.getMap('frontmatter')
      for (const [key, value] of Object.entries(note.frontmatter)) {
        if (fm.get(key) === undefined) fm.set(key, value)
      }
      return document
    },

    /**
     * Per-operation enforcement (audit rule): every inbound message
     * re-resolves live access. Throwing drops the message and kills the
     * connection — independent of the event-driven kick below.
     */
    // ponytail: per-message DB re-check; event-invalidated per-connection state if profiling demands
    async beforeHandleMessage({ documentName, context }) {
      const { userId } = context as ConnectionContext
      const { vaultId } = parseDocName(documentName)
      const access = await resolveAccess(userId, vaultId)
      if (!atLeast(access, 'edit')) throw new Error('access revoked')
    },

    async onStoreDocument({ documentName, document }) {
      const { vaultId, path } = parseDocName(documentName)
      const state = docState(document)
      try {
        await updateNote(vaultId, path, state)
      } catch (err) {
        // Invalid collab state (e.g. bad frontmatter): keep last valid file.
        console.error(`collab store rejected for ${documentName}:`, err)
      }
    },

    async onChange({ documentName, document }) {
      const { vaultId, path } = parseDocName(documentName)
      publishNoteState(vaultId, path, docState(document))
    },
  })

  await server.listen(port)
  wireKick(server.hocuspocus)
  currentInstance = server.hocuspocus
  return server
}

/** Event-driven kick: revocation closes affected sockets immediately. */
function wireKick(hocuspocus: Hocuspocus): void {
  onPermissionChange((change) => {
    hocuspocus.documents.forEach((doc, documentName) => {
      const { vaultId } = parseDocName(documentName)
      doc.getConnections().forEach((connection) => {
        const { userId } = connection.context as ConnectionContext
        if (!affects(change, userId, vaultId)) return
        void resolveAccess(userId, vaultId).then((access) => {
          if (!atLeast(access, 'edit')) connection.close()
        })
      })
    })
  })
}

import { EventEmitter } from 'node:events'

// ponytail: in-process bus; needs pg NOTIFY or similar if multi-process
export interface PermissionChange {
  /** Vaults whose access rules changed (share/transfer). */
  vaultIds?: string[]
  /** Users whose access anywhere may have changed (deactivation, membership). */
  userIds?: string[]
}

const bus = new EventEmitter()
bus.setMaxListeners(100)

export function emitPermissionChange(change: PermissionChange): void {
  bus.emit('change', change)
}

export function onPermissionChange(fn: (change: PermissionChange) => void): () => void {
  bus.on('change', fn)
  return () => bus.off('change', fn)
}

/** True if a connection identified by (userId, vaultId) is affected. */
export function affects(change: PermissionChange, userId: string, vaultId: string): boolean {
  if (change.userIds?.includes(userId)) return true
  if (change.vaultIds?.includes(vaultId)) return true
  return false
}

import type { FastifyInstance } from 'fastify'
import { atLeast, resolveAccess } from '../vaults/permissions.js'
import { readNote, splitPath } from '../notes/store.js'
import { addViewer } from './viewers.js'

/**
 * Read-only live view: SSE stream of note states. Viewers get the same
 * real-time content as editors but never join the Yjs doc — no
 * awareness, no identity data, no cursor broadcast (audit rule).
 */
export function syncRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  app.get<{ Params: { id: string; '*': string } }>(
    '/vaults/:id/live/*',
    async (req, reply) => {
      const vaultId = req.params.id
      const path = req.params['*']
      const access = await resolveAccess(req.user!.id, vaultId)
      if (!atLeast(access, 'read')) return reply.code(404).send({ error: 'not found' })
      splitPath(path)
      const note = await readNote(vaultId, path)
      if (!note) return reply.code(404).send({ error: 'note not found' })

      reply.hijack()
      reply.raw.writeHead(200, {
        'content-type': 'text/event-stream',
        'cache-control': 'no-cache',
        connection: 'keep-alive',
      })
      reply.raw.write(
        `data: ${JSON.stringify({ frontmatter: note.frontmatter, body: note.body })}\n\n`,
      )
      addViewer({ userId: req.user!.id, vaultId, path, reply })
    },
  )
}

